INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(1301, 'Genesis 44:20', 'Genesis', 44, 20, '&nbsp;نو مونږ درته ووئيل چې زمونږ پلار شته چې ضعيف سړے دے او زمونږ يو کشر ورور هم شته چې د هغۀ په بوډاتوب کښې پېدا شوے دے. د دې هلک ورور مړ دے او دا د مور يک يو ژوندے بچے دے. خپل پلار ورسره ډېره مينه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1302, 'Genesis 44:21', 'Genesis', 44, 21, '&nbsp;صاحِبه، تا مونږ ته وفرمائيل چې هغه دلته راولئ، چې تۀ هغه وګورې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1303, 'Genesis 44:22', 'Genesis', 44, 22, '&nbsp;او مونږ ووئيل چې هغه هلک د خپل پلار نه نۀ شى جدا کېدے، کۀ هغه جدا شى، نو د هغۀ پلار به مړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1304, 'Genesis 44:23', 'Genesis', 44, 23, '&nbsp;بيا تا وفرمائيل چې کۀ تاسو سره خپل کشرے ورور نۀ وى راغلے نو تاسو زما په دربار کښې نۀ شئ حاضرېدے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1305, 'Genesis 44:24', 'Genesis', 44, 24, '&nbsp;کله چې مونږ واپس خپل پلار له لاړُو، صاحِبه، چې تا څۀ فرمائيلى وُو هغه خبرې مو هغۀ ته وکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1306, 'Genesis 44:25', 'Genesis', 44, 25, '&nbsp;هغۀ مونږ ته وفرمائيل چې بيا لاړ شئ او لږه نوره غله واخلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1307, 'Genesis 44:26', 'Genesis', 44, 26, '&nbsp;مونږ ورته ووئيل چې مونږ تر هغې پورې نۀ شُو تلے، چې خپل کشرے ورور راسره نۀ وى نو مونږ د هغه سړى په دربار کښې نۀ شُو حاضرېدلے. مونږ صِرف په دې يو شرط تلے شُو کۀ کشرے ورور هم زمونږ سره لاړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1308, 'Genesis 44:27', 'Genesis', 44, 27, '&nbsp;زمونږ پلار مونږ ته وفرمائيل، تاسو ته پته ده چې زما د ښځې راحيل نه زما صِرف دوه زامن پېدا شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1309, 'Genesis 44:28', 'Genesis', 44, 28, '&nbsp;هغه يو خو زما نه مخکښې تلے دے. هغه به خامخا ځنګلى ځناورو ټوټې ټوټې کړے وى، ځکه چې ما بيا نۀ دے ليدلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1310, 'Genesis 44:29', 'Genesis', 44, 29, '&nbsp;کۀ تاسو اوس دے هم زما نه بوځئ او په هغۀ څۀ وشى نو تاسو چې په کوم غم ما آخته کوئ نو ما سپين‌ږيرے به غمژن قبر ته ولېږئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1311, 'Genesis 44:32', 'Genesis', 44, 32, '&nbsp;بله خبره دا ده چې، ما خپل پلار له خپل ځان په ضمانت کښې ورکړے دے. ما هغۀ ته وئيلى دى چې کۀ دا هلک مې واپس هغۀ له رانۀ وستلو، نو زۀ به همېشه دپاره هغۀ ته ملامته يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1312, 'Genesis 44:33', 'Genesis', 44, 33, '&nbsp;او اوس صاحِبه، د دې هلک په ځائ به زۀ ستا غلام شم، دے پرېږده چې واپس د خپلو وروڼو سره لاړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1313, 'Genesis 44:34', 'Genesis', 44, 34, '&nbsp;چې دا هلک زما سره نۀ وى نو زۀ څنګه واپس خپل پلار له لاړ شم؟ داسې غم چې زما په پلار راشى نو هغه زۀ نۀ شم زغملے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1314, 'Genesis 45:1', 'Genesis', 45, 1, '&nbsp;بيا يوسف د خپلو خِدمتګارانو په مخکښې زړۀ نۀ شو کلک کولے، نو هغۀ ټولو مِصريانو له حُکم ورکړو چې د هغۀ نه لاړ شى. نو د هغۀ سره نور هيڅ څوک هم نۀ وُو کله چې يوسف خپلو وروڼو ته خپل ځان وښودلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1315, 'Genesis 45:2', 'Genesis', 45, 2, '&nbsp;هغۀ دومره په چغو چغو وژړل چې مِصريانو هم دا ژړا واورېده او دا خبر د فِرعون محل ته ورسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1316, 'Genesis 45:3', 'Genesis', 45, 3, '&nbsp;يوسف خپلو وروڼو ته وفرمائيل، ”زۀ يوسف يم. ولې زما پلار لا ژوندے دے؟“ خو چې د هغۀ وروڼو دا واورېدل، هغوئ دومره ويرېدل چې هغوئ خبرې هم نۀ شوې کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1317, 'Genesis 45:4', 'Genesis', 45, 4, '&nbsp;بيا يوسف هغوئ ته وفرمائيل، ”ما ته لږ رانزدې شئ.“ او هغوئ ورنزدې شول نو هغۀ ورته وفرمائيل، ”زۀ ستاسو هغه ورور يوسف يم، کوم چې تاسو په مِصريانو خرڅ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1318, 'Genesis 45:5', 'Genesis', 45, 5, '&nbsp;اوس مۀ خفه کېږئ او مۀ خپل ځانونه ملامته کوئ چې تاسو دلته زۀ خرڅ کړم. بې‌شکه زۀ خُدائ پاک ستاسو نه مخکښې دلته راولېږلم چې د خلقو ژوند بچ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1319, 'Genesis 45:6', 'Genesis', 45, 6, '&nbsp;دا خو په زمکه د قحط صِرف دوېم کال دے، پينځۀ نور کالونه به هم وى چې کَرل او رېبل به په کښې نۀ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1320, 'Genesis 45:7', 'Genesis', 45, 7, '&nbsp;خُدائ پاک زۀ ستاسو نه مخکښې دلته رالېږلے يم چې تاسو په دُنيا کښې داسې په عجيبه طريقه بچ شئ او چې دا خبره يقينى وى چې تاسو او ستاسو اولاد ژوندى پاتې شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1321, 'Genesis 45:8', 'Genesis', 45, 8, '&nbsp;نو دا تاسو نۀ وئ، بلکې خُدائ پاک وو چې هغۀ زۀ دلته راولېږلم. هغۀ زۀ د فِرعون د ټولو نه لوئ وزير، د هغۀ د دربار مشر او په ټول مِصر مشر جوړ کړے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1322, 'Genesis 45:9', 'Genesis', 45, 9, '&nbsp;اوس زر زر واپس زما پلار له لاړ شئ او هغۀ ته ووايئ چې ستا زوئ يوسف داسې وائى، خُدائ پاک زۀ په ټول مِصر مشر جوړ کړے يم، زر زر ما له راشه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1323, 'Genesis 45:10', 'Genesis', 45, 10, '&nbsp;تاسو به د جشن په علاقه کښې اوسېږئ، چرته چې به تۀ، ستاسو بچى، نمسى، ستاسو ګډې، چېلۍ، څاروى او ستاسو هر څۀ به ما ته نزدې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1324, 'Genesis 45:11', 'Genesis', 45, 11, '&nbsp;کۀ تاسو په جشن کښې يئ نو زۀ به ستاسو خيال ساتم. د قحط پينځۀ کالونه خو لا پاتې دى، او زۀ دا نۀ غواړم چې تاسو، ستاسو خاندان او ستاسو څاروى دې د لوږې نه مړۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1325, 'Genesis 45:12', 'Genesis', 45, 12, '&nbsp;او ګورئ، اوس بنيامين او تاسو هم ما وينئ چې زۀ په رښتيا يوسف يم چې ستاسو سره خبرې کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1326, 'Genesis 45:13', 'Genesis', 45, 13, '&nbsp;زما پلار ته ووايئ چې ما ته دلته په مِصر کښې څومره عزت مِلاو شوے دے او هغه هر څۀ ورته ووايئ چې تاسو ليدلى دى. او زر زر يې دلته راولئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1327, 'Genesis 45:14', 'Genesis', 45, 14, '&nbsp;هغۀ د خپل ورور بنيامين نه لاسونه تاو کړل او وې ژړل، بنيامين هم وژړل چې کله ورغاړه وتو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1328, 'Genesis 45:15', 'Genesis', 45, 15, '&nbsp;بيا په ژړا ژړا کښې، هغۀ خپل ټول وروڼه غاړه ويستل او ښُکل يې کړل. د هغې نه پس ورسره وروڼو خبرې اترې شروع کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1329, 'Genesis 45:16', 'Genesis', 45, 16, '&nbsp;چې کله دا خبر محل ته ورسېدو چې د يوسف وروڼه راغلى دى، نو فِرعون او د هغۀ درباريان خوشحاله شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1330, 'Genesis 45:17', 'Genesis', 45, 17, '&nbsp;فِرعون يوسف ته ووئيل، ”خپلو وروڼو ته ووايه چې خپل څاروى بار کړى او د کنعان مُلک ته دې واپس لاړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1331, 'Genesis 45:18', 'Genesis', 45, 18, '&nbsp;هغوئ دې خپل پلار او خپل خاندان دلته راولى او دلته دې واپس راشى. زۀ به دوئ له په مِصر کښې د ټولو نه ښۀ زمکه ورکړم او هغوئ به د هغې زمکې نه ښۀ ډېره ګټه واخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1332, 'Genesis 45:19', 'Genesis', 45, 19, '&nbsp;هغوئ ته دا هم ووايه چې د مِصر نه خپل ځان سره ګاډۍ بوځى چې په کښې خپلې ښځې، ماشومان او خپل پلار د ځان سره راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1333, 'Genesis 45:20', 'Genesis', 45, 20, '&nbsp;د هغوئ نه چې کوم مالونه او سامانونه پاتې شى د هغې غم دې نۀ کوى، ځکه چې په مِصر کښې د ټولو نه ښۀ زمکه به د هغوئ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1334, 'Genesis 45:21', 'Genesis', 45, 21, '&nbsp;د يعقوب زامنو هم هغه شان وکړل چې څنګه فِرعون حُکم کړے وو. نو يوسف هغوئ له ګاډۍ او د سفر دپاره خوراک هم ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1335, 'Genesis 45:22', 'Genesis', 45, 22, '&nbsp;هغۀ هر يو له د جامو نوې جوړې هم ورکړې، خو هغۀ بنيامين له درې سوه د سپينو زرو سيکې او پينځۀ جوړه نوې جامې ورکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1336, 'Genesis 45:23', 'Genesis', 45, 23, '&nbsp;هغۀ خپل پلار له د مِصر په ښۀ سامانونو بار لس خرې او لس د غلې بار خرې، روټۍ او د سفر دپاره خوراک هم ورولېږلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1337, 'Genesis 45:24', 'Genesis', 45, 24, '&nbsp;هغۀ خپل وروڼه رُخصت کړل او چې هغوئ څنګه روان شول هغۀ هغوئ ته وفرمائيل، ”په لاره کښې بحث مۀ کوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1338, 'Genesis 45:25', 'Genesis', 45, 25, '&nbsp;دوئ د مِصر نه روان شول او د کنعان په مُلک کښې خپل پلار او کور ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1339, 'Genesis 45:26', 'Genesis', 45, 26, '&nbsp;هغوئ هغۀ ته ووئيل چې، ”يوسف ژوندے دے. هغه د ټول مِصر مشر دے.“ يعقوب حق حېران شو او د هغوئ په خبرو يې يقين نۀ راتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1340, 'Genesis 45:27', 'Genesis', 45, 27, '&nbsp;خو چې کله هغوئ ورته هغه هر څۀ ووئيل کوم چې يوسف هغوئ ته فرمائيلى وُو او چې هغه ګاډۍ يې هم وليدلې کومې چې يوسف رالېږلې وې چې هغه به په کښې مِصر ته بوځى، نو د هغوئ پلار يعقوب کښې ساه راغله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1341, 'Genesis 45:28', 'Genesis', 45, 28, '&nbsp;هغۀ وفرمائيل، ”زما زوئ يوسف ژوندے دے. بس هم دغه مې غوښتل. زۀ ورځم چې د خپل مرګ نه مخکښې يې ووينم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1342, 'Genesis 46:1', 'Genesis', 46, 1, '&nbsp;يعقوب د خپل هر څۀ سره په خپل سفر روان شو او بيرسبع ته راغلو. هلته يې د خپل پلار اِسحاق خُدائ پاک ته قربانۍ پېش کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1343, 'Genesis 46:2', 'Genesis', 46, 2, '&nbsp;د شپې خُدائ پاک په خوب کښې د هغۀ سره خبرې وکړې او ورته يې وفرمائيل، ”يعقوبه، يعقوبه.“ هغۀ ورته وفرمائيل، ”آو، زۀ حاضر يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1344, 'Genesis 46:3', 'Genesis', 46, 3, '&nbsp;ورته يې وفرمائيل، ”زۀ ستا د پلار خُدائ پاک يم. مِصر ته تلو نه مۀ يرېږه، زۀ به هلته ستا د اولاد نه يو لوئ قوم جوړوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1345, 'Genesis 46:4', 'Genesis', 46, 4, '&nbsp;زۀ تا سره مِصر ته تلو کښې مل يم او زۀ به ستا اولاد واپس دې مُلک ته راولم. چې تۀ وفات شې نو يوسف به تا کفن دفن کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1346, 'Genesis 46:5', 'Genesis', 46, 5, '&nbsp;نو يعقوب د بيرسبع نه روان شو. د هغۀ زامنو، هغه، خپل واړۀ بچى او خپلې ښځې يې په هغه ګاډو کښې کښېنولې کومې چې فِرعون رالېږلې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1347, 'Genesis 46:6', 'Genesis', 46, 6, '&nbsp;هغوئ خپل څاروى او هغه هر څۀ کوم چې دوئ په کنعان کښې ګټلى وُو، روان کړل او مِصر ته لاړل. يعقوب د ځان سره خپل ټول اولاد روان کړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1348, 'Genesis 46:7', 'Genesis', 46, 7, '&nbsp;خپل زامن، نمسى، خپلې لوڼه او نمسۍ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
