(1375, 'Genesis 46:34', 'Genesis', 46, 34, '&nbsp;نو هغۀ ته ووايئ چې تاسو د وړوکوالى نه تر اوسه پورې څاروى ساتئ، لکه څنګه چې ستاسو پلار نيکۀ ساتل. نو داسې هغه به تاسو د جشن په علاقه کښې اوسېدو ته پرېږدى.“ يوسف داسې ځکه وفرمائيل چې مِصريانو شپانو ته په سپک نظر کتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1376, 'Genesis 47:1', 'Genesis', 47, 1, '&nbsp;نو يوسف د هغوئ نه پينځۀ وروڼه روان کړل او فِرعون له ورغلل. هغۀ فِرعون ته وفرمائيل، ”زما پلار او زما وروڼه د خپلو رَمو، څاروو او چې څۀ يې هم لرل د هغې سره د کنعان د مُلک نه راغلى دى. دوئ اوس د جشن په علاقه کښې دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1377, 'Genesis 47:2', 'Genesis', 47, 2, '&nbsp;هغۀ بيا خپل وروڼه د فِرعون سره مِلاو کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1378, 'Genesis 47:3', 'Genesis', 47, 3, '&nbsp;فِرعون د هغوئ نه تپوس وکړو، ”ستاسو کسب څۀ دے؟“ هغوئ ورته ووئيل، ”صاحِبه، مونږ شپانۀ يُو، لکه څنګه چې زمونږ پلار نيکۀ وُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1379, 'Genesis 47:4', 'Genesis', 47, 4, '&nbsp;”مونږ دې مُلک ته د اوسېدو دپاره راغلى يُو، ځکه چې د کنعان په مُلک کښې ډېر سخت قحط دے او زمونږ د څاروو د څرېدلو ځائ نشته. صاحِبه، مونږ تا ته سوال کوُو، مونږ له اجازت راکړه چې د جشن په علاقه کښې اوسيږو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1380, 'Genesis 47:5', 'Genesis', 47, 5, '&nbsp;فِرعون يوسف ته ووئيل، ”اوس ستا پلار او ستا وروڼه راغلى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1381, 'Genesis 47:6', 'Genesis', 47, 6, '&nbsp;نو د ټول مِصر زمکه د دوئ شوه. دوئ پرېږده چې د جشن په علاقه کښې اوسيږى چې د دې مُلک د ټولو نه ښۀ ځائ دے. او کۀ په دوئ کښې تکړه کسان وى، نو هغوئ زما په خپلو څاروو مشران مقرر کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1382, 'Genesis 47:7', 'Genesis', 47, 7, '&nbsp;بيا يوسف خپل پلار يعقوب راوستلو او د فِرعون سره يې مِلاو کړو. يعقوب فِرعون ته د برکت دپاره دُعا وکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
