(1388, 'Genesis 47:13', 'Genesis', 47, 13, '&nbsp;قحط دومره سخت وو چې هيچرته هم روټۍ نۀ مِلاوېدله او د مِصر او د کنعان د مُلک خلق د لوږې نه کمزورى شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1389, 'Genesis 47:14', 'Genesis', 47, 14, '&nbsp;چې خلقو به ترې نه غله اخستله، نو يوسف هغه ټولې روپۍ جمع کولې او هغه روپۍ به يې د فِرعون په خزانه کښې کېښودلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1390, 'Genesis 47:15', 'Genesis', 47, 15, '&nbsp;چې کله په مِصر او د کنعان په مُلک کښې ټولې روپۍ ختمې شوې، مِصريان يوسف له راغلل او ورته يې ووئيل، ”مونږ له روټۍ راکړه. ولې دا به ستا خوښه وى څۀ چې مونږ ستا په وړاندې مړۀ شُو. ځکه چې زمونږ سره ټولې روپۍ ختمې شوې دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1391, 'Genesis 47:16', 'Genesis', 47, 16, '&nbsp;يوسف ورته وفرمائيل، ”خپل څاروى راولئ، کۀ تاسو سره ټولې روپۍ ختمې شوې وى نو د څاروو په بدل کښې به زۀ تاسو له خوراک درکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1392, 'Genesis 47:17', 'Genesis', 47, 17, '&nbsp;نو هغوئ خپل څاروى يوسف له راوستل او هغۀ په دې کال کښې د هغوئ د آسونو، ګډو، چېلو، څاروو او خرو په بدل کښې خوراک ورکولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1393, 'Genesis 47:18', 'Genesis', 47, 18, '&nbsp;ورپسې کال هغوئ هغۀ له راغلل او ورته يې ووئيل، ”صاحِبه، مونږ به دا حقيقت ستا نه نۀ پټوُو، چې زمونږ سره ټولې روپۍ ختمې شوې او زمونږ څاروى هم ستا شول. زمونږ سره زمونږ د زمکو او زمونږ د ځانونو نه بغېر هيڅ هم پاتې نۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1394, 'Genesis 47:19', 'Genesis', 47, 19, '&nbsp;ولې دا به ستا خوښه وى څۀ چې مونږ ستا په وړاندې مړۀ شُو. زمونږ زمکه شاړه کېدو ته مۀ پرېږده. د خوراک په بدل کښې مونږ او زمونږ زمکه واخله. مونږ به د فِرعون نوکران شُو او زمونږ زمکه به د هغۀ شى. مونږ له غله راکړه چې ژوندى پاتې شُو او تخم راکړه چې زمکه وکَرو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1395, 'Genesis 47:20', 'Genesis', 47, 20, '&nbsp;نو يوسف د مِصر ټوله زمکه د فِرعون دپاره واخستله. هر يو مِصرى خپله زمکه د مجبورۍ نه خرڅه کړه، ځکه چې قحط ډېر سخت وو، او هغه ټوله زمکه د فِرعون شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1396, 'Genesis 47:21', 'Genesis', 47, 21, '&nbsp;يوسف د مِصر د يو سر نه تر بل سَره پورې خلق غلامان کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1397, 'Genesis 47:22', 'Genesis', 47, 22, '&nbsp;خو صِرف هغه زمکه يې وانۀ خستله کومه زمکه چې د اِمامانو وه. هغوئ دپاره دا ضرورى نۀ وه چې خپله زمکه خرڅه کړى، ځکه چې فِرعون هغوئ له د اوسېدو دپاره وظيفه ورکوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1398, 'Genesis 47:23', 'Genesis', 47, 23, '&nbsp;نو يوسف هغه خلقو ته وفرمائيل، ”تاسو ته پته ده چې ما تاسو او ستاسو زمکې هم د فِرعون دپاره اخستې دى. د خپلې خپلې زمکې کَرلو دپاره دا تخم واخلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1399, 'Genesis 47:24', 'Genesis', 47, 24, '&nbsp;د رېبلو په وخت کښې پينځمه حِصه فِرعون له ورکوئ. باقى نور تخم تاسو د کَرلو دپاره او د خپلو ځانونو، کورَنو او د خپلو وړو ماشومانو دپاره د خوراک په توګه استعمالولے شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1400, 'Genesis 47:25', 'Genesis', 47, 25, '&nbsp;هغوئ ورته ووئيل، ”تا زمونږ ژوند بچ کړے دے، صاحِبه. تۀ په مونږ مهربان يې او مونږ به د فِرعون غلامان يُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');